import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Code Walkthroughs: Paddles","description":"","frontmatter":{"title":"Ceph Code Walkthroughs: Paddles","date":"2021-10-07T00:00:00.000Z","updated":"2021-10-08T00:00:00.000Z","tags":["[Ceph]","[Distributed Storage]","[Integration Testing]","[Paddles Framework]","[Database Wrapper]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Code_Walkthroughs_-_Paddles.md","filePath":"posts/2021/Ceph_Code_Walkthroughs_-_Paddles.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Code_Walkthroughs_-_Paddles.md"};function r(s,l,d,n,h,u){return e(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议对Ceph的Paddles代码进行了详细的走查，重点是介绍Paddles作为集成测试框架关键组件的作用和结构。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>Paddles简介</strong>：</p><ul><li>Paddles是一个数据库包装器，用于存储和处理测试节点信息、任务状态更新等。</li><li>使用PostgreSQL作为后端数据库。</li></ul></li><li><p><strong>Toothology任务调度流程</strong>：</p><ul><li>Toothology调度器将任务添加到Beanstalk队列，并通过Paddles存储任务ID和配置参数。</li><li>任务状态更新也通过Paddles进行。</li></ul></li><li><p><strong>Paddles的模块结构</strong>：</p><ul><li>使用轻量级Web框架Pecan，遵循MVC模式。</li><li>模型定义数据库操作，控制器处理HTTP请求。</li></ul></li><li><p><strong>Paddles的配置和启动</strong>：</p><ul><li>配置文件包含服务器配置，如主机、端口、Pecan应用配置等。</li><li>使用Pecan的transaction hook处理数据库事务。</li></ul></li><li><p><strong>模型和控制器详细介绍</strong>：</p><ul><li>模型定义节点、任务和运行的表结构和操作。</li><li>控制器处理HTTP请求，如获取节点信息、锁定和解锁节点、创建和更新任务等。</li></ul></li><li><p><strong>Alembic数据迁移框架</strong>：</p><ul><li>用于在不停止运行的情况下修改数据库模式。</li><li>通过创建修订号来管理数据库模式的版本。</li></ul></li><li><p><strong>测试和部署</strong>：</p><ul><li>使用Green Unicorn作为生产环境的服务器。</li><li>编写了多个测试用例，包括模型测试和控制器测试。</li></ul></li><li><p><strong>Paddles的持续改进</strong>：</p><ul><li>正在添加排队机制，以消除对Beanstalk的依赖。</li><li>新的排队机制允许在任务排队后更新任务优先级等特性。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>确认Paddles的关键功能和结构，以及其在Toothology集成测试框架中的作用。</li><li>确认使用Alembic进行数据库模式迁移的方法。</li><li>确认使用Green Unicorn进行生产环境部署的方法。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发和完善Paddles的排队机制。</li><li>持续进行代码测试和优化，确保系统的稳定性和性能。</li><li>定期进行代码走查和知识分享，以提高团队的技术水平和协作效率。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>鼓励团队成员在会议录像中留下问题或评论，以便进一步讨论和澄清。</li><li>计划在下个月进行另一个代码走查，具体主题待定。</li></ul>',11)])])}const c=a(o,[["render",r]]);export{_ as __pageData,c as default};
